using System.Windows;using LabMaster.Services;namespace LabMaster;public partial class AddQCWindow:Window{readonly QCService service=new();readonly TestMasterService tests=new();public AddQCWindow(){InitializeComponent();Loaded+=async(_,_)=>TestBox.ItemsSource=await tests.GetDepartmentsAsync();}async void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(MaterialBox.Text)||!decimal.TryParse(MeanBox.Text,out var mean)||!decimal.TryParse(SdBox.Text,out var sd)){Status.Text="Material, mean and SD are required.";return;}try{await service.AddAsync(MaterialBox.Text,LotBox.Text,null,mean,sd,ExpiryBox.SelectedDate);DialogResult=true;}catch(Exception ex){Status.Text=ex.Message;}}}